#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll LIMIT = 1'000'000'000LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, q;
        cin >> n >> q;
        vector<ll> A(n);
        for (int i = 0; i < n; ++i) cin >> A[i];

        vector<ll> ans(n + 1, 0); // 1-indexed

        int i = 0;
        while (i < n) {
            if (A[i] == 0) {
                ++i;
                continue;
            }
            int j = i;
            while (j < n && A[j] != 0) ++j;
            int m = j - i;
            vector<ll> seg(A.begin() + i, A.begin() + j);

            bool allOnes = true;
            for (ll x : seg) {
                if (x != 1) {
                    allOnes = false;
                    break;
                }
            }

            if (allOnes) {
                for (int L = 1; L <= m; ++L) {
                    ans[L] += (ll)(m - L + 1);
                }
            } else {
                for (int start = 0; start < m; ++start) {
                    ll prod = 1;
                    for (int end = start; end < m; ++end) {
                        if (prod > LIMIT / seg[end]) break;
                        prod *= seg[end];
                        if (prod > LIMIT) break;
                        int length = end - start + 1;
                        ans[length] += prod;
                    }
                }
            }
            i = j;
        }

        for (int k = 0; k < q; ++k) {
            int L;
            cin >> L;
            cout << ans[L] << '\n';
        }
    }
    return 0;
}
